function DexUI.rowsForGame(game)
  local generation=GoldCompat.generation
  local rows={}
  for _,row in ipairs(DexUI.uiRows) do
    if not row.gen or row.gen==generation then
      rows[#rows+1]=row
    end
  end
  return rows
end

-- Colosseum Overhaul merge: the paired UI mod used to persist its own
-- settings under the literal id "colosseum_ui_overhaul" (a separate mod
-- from CBE, each with their own manifest id). Existing players upgrading
-- from the two separate mods to this merged one would otherwise see their
-- saved UI preferences (including colosseumBattleUI, which gates whether
-- doubles battles are even allowed to start) silently reset, since the
-- on-disk options file and the in-memory loader cache are both keyed by mod
-- id and the id has changed. This copies the old bucket forward exactly
-- once -- in the in-memory loader cache and in the on-disk options file --
-- and never overwrites an already-migrated (or freshly re-chosen) bucket
-- already sitting under the new id. Safe to call repeatedly/from multiple
-- entry points: it is a no-op after the first successful migration.
local LEGACY_UI_MOD_ID="colosseum_ui_overhaul"
function GoldCompat.migrateLegacyModOptions(game)
  if GoldCompat.__legacyOptionsMigrated then return end
  game=game or (modRef and modRef.game)
  local newId=modRef and modRef.id
  local loader=game and game.mods
  if not (newId and newId~=LEGACY_UI_MOD_ID and loader) then return end
  GoldCompat.__legacyOptionsMigrated=true
  pcall(function()
    loader.modOptions=loader.modOptions or {}
    local legacy=loader.modOptions[LEGACY_UI_MOD_ID]
    if type(legacy)=="table" and next(legacy)~=nil and loader.modOptions[newId]==nil then
      loader.modOptions[newId]=legacy
    end
    local SaveData=require("src.core.SaveData")
    local fs=loader.fs
    if not (fs and fs.write) then return end
    local opts=SaveData.loadOptions(fs)
    opts.modOptions=opts.modOptions or {}
    local legacyOnDisk=opts.modOptions[LEGACY_UI_MOD_ID]
    local currentOnDisk=opts.modOptions[newId]
    if type(legacyOnDisk)=="table" and next(legacyOnDisk)~=nil
        and (currentOnDisk==nil or next(currentOnDisk)==nil) then
      opts.modOptions[newId]=legacyOnDisk
      SaveData.saveOptions(opts,fs)
    end
  end)
end

function DexUI.setOption(game,key,value)
  local loader=game and game.mods
  if not loader then return false end
  GoldCompat.migrateLegacyModOptions(game)

  local modId=(modRef and modRef.id) or LEGACY_UI_MOD_ID
  loader.modOptions=loader.modOptions or {}
  local bucket=loader.modOptions[modId]
  if not bucket then
    bucket={}
    loader.modOptions[modId]=bucket
  end
  bucket[key]=value
  GoldCompat.invalidateOptionValue(key,value,true)

  -- Persist through the same options file used by the mod manager. The public
  -- options facade is intentionally read-only at runtime, so this in-game UI
  -- uses the engine-owned SaveData serializer rather than inventing storage.
  local okSave=pcall(function()
    local SaveData=require("src.core.SaveData")
    local fs=loader.fs
    if not (fs and fs.write) then return end
    local opts=SaveData.loadOptions(fs)
    opts.modOptions=opts.modOptions or {}
    opts.modOptions[modId]=opts.modOptions[modId] or {}
    opts.modOptions[modId][key]=value
    SaveData.saveOptions(opts,fs)
  end)

  -- Match ManagerState's runtime notification contract when available.
  pcall(function()
    if loader.events and loader.events.emit then
      loader.events:emit("mod.options_changed",
        {mod=modId,key=key,value=value})
    end
  end)

  return okSave or true
end

function DexUI.optionDisplay(row)
  local value=optionValue(row.key)
  if row.kind=="toggle" then
    return value~=false and "ON" or "OFF"
  end
  if row.display then
    local mapped=row.display[value]
    if mapped then return tostring(mapped) end
  end
  return tostring(value or ""):upper()
end

function DexUI.activateUIRow(game,row)
  if not row then return end
  if row.kind=="toggle" then
    DexUI.setOption(game,row.key,not featureEnabled(row.key))
    return
  end

  if row.kind=="choice" and row.values and #row.values>0 then
    local current=optionValue(row.key)
    local index=1
    for i,value in ipairs(row.values) do
      if value==current then index=i break end
    end
    index=index<#row.values and index+1 or 1
    DexUI.setOption(game,row.key,row.values[index])
  end
end


local function bagStateForMenu(game)
  if not (game and game.stack and game.stack.states) then return nil end
  for i=#game.stack.states,1,-1 do
    local state = game.stack.states[i]
    if state and state.__gen3uiBag then
      return state
    end
  end
  return nil
end


local function stateExistsInStack(game, target)
  if not (game and game.stack and game.stack.states and target) then return false end
  for _,state in ipairs(game.stack.states) do
    if state == target then return true end
  end
  return false
end

function GoldCompat.colosseumPartyFlowActive(game)
  if not featureEnabled("colosseumPokemonMenu") then return false end
  if not (game and game.stack and game.stack.states) then return false end
  for _,state in ipairs(game.stack.states) do
    if state and (state.__gen3uiColosseumParty
        or state==State.activeParty
        or state==State.activeTMParty
        or state==State.activeItemTargetParty) then
      return true
    end
  end
  return State.activeBattleMoveParty~=nil
      and State.activeBattleMoveLearn~=nil
      and stateExistsInStack(game,State.activeBattleMoveLearn)
end

local function battleStateInStack(game)
  if not (game and game.stack and game.stack.states) then return nil end
  for i=#game.stack.states,1,-1 do
    local state=game.stack.states[i]
    if getmetatable(state)==BattleState
        or state==State.activeBattle
        or GoldCompat.isGen2BattleState(state) then
      return state
    end
  end
  return nil
end

-- Native battle.bottom_ui_visible also suppresses pushed TextBox/ChoiceBox
-- states. Their replacement must follow battle ownership, not the independent
-- OVERWORLD dialogue toggle, or a real input prompt becomes invisible.
function GoldCompat.dialoguePresentationEnabled(state)
  if featureEnabled("revampedDialogueBoxes") then return true end
  local game=state and state.game
  local battle=game and battleStateInStack(game)
  return battle and GoldCompat.battlePresentationEnabledFor(battle) or false
end

function GoldCompat.inheritBattleSurfaceFlag(state,methodName)
  local game=(state and state.game) or (modRef and modRef.game) or GoldCompat.game
  local battle=battleStateInStack(game)
  if not battle or battle==state then return nil end
  local fn=battle[methodName]
  if type(fn)=="function" then
    local ok,value=pcall(fn,battle)
    if ok then return value==true end
  end
  -- Gen II BattleState is intrinsically a wide/fill battle screen. Older
  -- launcher builds asked only the top overlay for these flags, so returning
  -- the inherited truth here prevents a transparent Bag/Party/TextBox from
  -- collapsing CBE's arena back into the 160x144 path for one frame.
  if GoldCompat.isGen2BattleState(battle) then return true end
  return nil
end

-- Gen II's compositor treats the topmost state that advertises a widescreen
-- draw as the owner of the physical battle surface.  If a transparent menu
-- merely inherits `drawsWidescreen=true` but its own drawWidescreen is a no-op,
-- Game2 falls back to drawing the complete stack again in a centered 160x144
-- panel.  With CBE/Stadium/other world providers this produces the duplicated
-- arena/lens rectangle behind Bag/Party/Summary.
--
-- Keep the menu as the top widescreen owner, but delegate ONLY its background
-- draw to the authoritative battle state.  The custom menu itself is painted
-- later in render.hud.  This is provider-agnostic: CBE, Stadium, Battle Arts,
-- vanilla, or any future battle renderer sees its normal BattleState seam once.
function GoldCompat.drawBattleWidescreenUnderOverlay(state,winW,winH)
  if GoldCompat.generation~="gen2" then return false end
  local game=(state and state.game) or (modRef and modRef.game) or GoldCompat.game
  local battle=battleStateInStack(game)
  if not battle or battle==state or type(battle.drawWidescreen)~="function" then
    return false
  end
  local ok,err=pcall(battle.drawWidescreen,battle,winW,winH)
  if not ok then
    if modRef and modRef.log then
      pcall(function()
        modRef.log("error","Colosseum UI: Gen II battle widescreen proxy failed: "
          ..tostring(err))
      end)
    end
    return false
  end
  return true
end

function GoldCompat.uiOwnsBattleOverlayState(state)
  if not state or state.__gen3uiDisableBattleSurfaceProxy then return false end

  -- One explicit marker is enough for every new UI flow going forward. The
  -- legacy markers below keep all existing 2.x screens covered without
  -- rewriting their gameplay/state logic just to rename a flag.
  if state.__gen3uiBattleOverlay or state.__gen3uiGoldOverlayKind
      or state.__colosseumFlowKind then return true end

  if state.__gen3uiBag or state.__gen3uiBagAction
      or state.__gen3uiColosseumParty or state.__gen3uiColosseumSummary
      or state.__gen3uiItemTarget or state.__gen3uiKeepTMBackground
      or state.__gen3uiPPMovePicker or state.__gen3uiBattleMoveParty
      or state.__gen3uiGoldBattleMoveParty or state.__gen3uiPPMoveParty
      or state.__gen3uiPPParty or state.__gen3uiLevelUpBox
      or state.__colosseumCaughtNaming or state.__colosseumGiftNaming then
    return true
  end

  if GoldCompat.isDialogueTextState and GoldCompat.isDialogueTextState(state)
      and GoldCompat.dialoguePresentationEnabled(state) then return true end
  if GoldCompat.isDialogueChoiceState
      and GoldCompat.isDialogueChoiceState(state)
      and GoldCompat.dialoguePresentationEnabled(state) then return true end

  return state==State.activeBattleMoveLearn
      or state==State.activeBattleMoveParty
      or state==State.activeBattleStatBox
      or state==State.activeItemTargetParty
      or state==State.activeTMParty
end

function GoldCompat.isBattleWidescreenOverlay(state)
  if GoldCompat.generation~="gen2" or not state then return false end
  local game=state.game or (modRef and modRef.game) or GoldCompat.game
  local battle=battleStateInStack(game)
  if not battle or battle==state then return false end

  -- 2.1.9: compositor ownership is a property of the STACK, not a curated
  -- list of individual screen names. Every presentation state owned by this
  -- overhaul uses the same contract; opaque/native full-screen states and
  -- unrelated third-party transparent states are left completely untouched.
  return state.isOpaque~=true and GoldCompat.uiOwnsBattleOverlayState(state)
end

function GoldCompat.stateAboveBattle(state)
  if GoldCompat.generation~="gen2" or not state then return false,nil end
  local game=state.game or (modRef and modRef.game) or GoldCompat.game
  local states=game and game.stack and game.stack.states
  if type(states)~="table" then return false,nil end
  local battleIndex,stateIndex,battle=nil,nil,nil
  for i=#states,1,-1 do
    local st=states[i]
    if st==state and not stateIndex then stateIndex=i end
    if not battleIndex and (getmetatable(st)==BattleState
        or st==State.activeBattle or GoldCompat.isGen2BattleState(st)) then
      battleIndex=i
      battle=st
    end
  end
  return battleIndex~=nil and stateIndex~=nil and stateIndex>battleIndex,battle
end

-- Apply the Gen II hanging-surface contract to an INSTANCE as soon as it is
-- pushed. This catches every UI-owned battle flow -- Pokédex, NamingScreen,
-- nickname entry, move learning, item prompts, and future overhaul states --
-- without requiring each class to know about Game2's compositor.
--
-- Game2 treats the top state with drawsWidescreen()+drawWidescreen() as the
-- physical surface owner. If a transparent state above BattleState does not
-- advertise that ownership, Game2 chooses the battle as `wide` and then
-- executes its `wide ~= top` fallback, which redraws StateStack inside a
-- centred 160x144 panel. The proxy below makes the TOP overlay own that seam
-- while delegating only the background draw to BattleState.
function GoldCompat.installBattleSurfaceProxy(state)
  if GoldCompat.generation~="gen2" or type(state)~="table"
      or state.__gen3uiBattleSurfaceProxy then return false end
  local above,battle=GoldCompat.stateAboveBattle(state)
  if not above or not battle or state.isOpaque==true
      or not GoldCompat.uiOwnsBattleOverlayState(state) then return false end

  local originalDraws=state.drawsWidescreen
  local originalDrawWide=state.drawWidescreen
  local originalFill=state.wantsFillScale
  state.__gen3uiBattleSurfaceProxy=true
  state.__gen3uiBattleSurfaceOriginalDraws=originalDraws
  state.__gen3uiBattleSurfaceOriginalDrawWide=originalDrawWide
  state.__gen3uiBattleSurfaceOriginalFill=originalFill

  state.drawsWidescreen=function(self,...)
    if GoldCompat.isBattleWidescreenOverlay(self) then return true end
    if type(originalDraws)=="function" then return originalDraws(self,...) end
    return false
  end
  state.wantsFillScale=function(self,...)
    if GoldCompat.isBattleWidescreenOverlay(self) then
      local inherited=GoldCompat.inheritBattleSurfaceFlag(self,"wantsFillScale")
      if inherited~=nil then return inherited end
      return true
    end
    if type(originalFill)=="function" then return originalFill(self,...) end
    return false
  end
  state.drawWidescreen=function(self,winW,winH,...)
    if GoldCompat.isBattleWidescreenOverlay(self) then
      if GoldCompat.drawBattleWidescreenUnderOverlay(self,winW,winH) then return end
    end
    if type(originalDrawWide)=="function" then
      return originalDrawWide(self,winW,winH,...)
    end
  end
  return true
end

local function makeBattleMovePartyState(game,moveMenu)
  if not (game and moveMenu and moveMenu.mon) then return nil end

  local party=(game.save and game.save.party) or {}
  local selected=1
  for i,mon in ipairs(party) do
    if mon==moveMenu.mon then
      selected=i
      break
    end
  end

  local state={
    game=game,
    party=party,
    index=selected,
    selected=selected,
    blink=0,
    keepOpen=true,
    __gen3uiBattleMoveParty=true,
  }

  -- drawPartyFinal expects this method on a real PartyMenu.
  function state:bottomMessage()
    return "Choose a move to replace."
  end

  return state
end

-- Gold does not push src.ui.MoveLearnMenu during battle. Its BattleState owns
-- the complete ForgetMove flow in-place through pendingLearn/forgetIndex.
-- Adapt those authoritative fields to the same small presentation contract the
-- Party renderer already consumes for TM/HM and Gen I battle move learning.
local function makeGoldBattleMovePartyState(game,battleState)
  local learn=battleState and battleState.pendingLearn
  local battle=battleState and battleState.battle
  local party=(battle and battle.party) or (game.save and game.save.party) or {}
  local index=learn and tonumber(learn.index) or 1
  index=math.max(1,math.min(index,math.max(1,#party)))
  local mon=party[index]
  if not (learn and mon) then return nil,nil end

  local adapter={
    game=game,
    mon=mon,
    -- Gold queues the fully constructed move entry, not merely its id.
    newMoveId=type(learn.move)=="table"
      and (learn.move.id or learn.move.moveId or learn.move.move)
      or learn.move,
    index=math.max(1,tonumber(battleState.forgetIndex) or 1),
    selecting=true,
    __goldBattleState=battleState,
  }
  local state={
    game=game,party=party,index=index,selected=index,blink=0,keepOpen=true,
    __gen3uiBattleMoveParty=true,
    __gen3uiGoldBattleMoveParty=true,
  }
  function state:bottomMessage() return "Choose a move to replace." end
  return state,adapter
end

-- This was referenced by name at the in-battle move-learn render dispatch
-- but never actually defined anywhere in the file, so every call silently
-- failed via pcall -- which is why that flow appeared broken (falling
-- through to whatever the battle's own move-select UI last showed, i.e.
-- the active battler's moves, instead of the Pokémon actually learning the
-- new move). GoldCompat.drawColosseumParty already has a complete, working
-- presentation for this exact moment (its __gen3uiBattleMoveParty branch:
-- full party grid with the learning Pokémon's card selected, its current
-- moves shown in the detail panel with the pending replacement highlighted
-- and the new move named) -- makeBattleMovePartyState() above was already
-- built specifically to feed that path, so route into it directly instead
-- of maintaining a second, separate renderer.
local function drawBattleMoveLearnFinal(battle,moveMenu)
  local partyState=State.activeBattleMoveParty
  if not (partyState and partyState.game) then return false end
  return GoldCompat.drawGoldPartyMenu(partyState,
    love.graphics.getWidth(),love.graphics.getHeight())
end


local function shopMenuLabel(item)
  return tostring(item and item.label or ""):upper()
end

local function shopMainItems(items)
  if type(items)~="table" or #items~=3 then return false end
  return shopMenuLabel(items[1])=="BUY"
      and shopMenuLabel(items[2])=="SELL"
      and shopMenuLabel(items[3])=="QUIT"
end


local function shopStateInStack(game)
  if not (game and game.stack and game.stack.states) then return nil end
  for i=#game.stack.states,1,-1 do
    local state=game.stack.states[i]
    if state and (state.__gen3uiShopList or state.__gen3uiShopMain) then
      return state
    end
  end
  return nil
end

local function pcMenuLabel(item)
  return tostring(item and item.label or ""):upper()
end

local function pcAccessItems(items)
  if type(items)~="table" or #items<2 then return false end
  local hits=0
  for _,item in ipairs(items) do
    local label=pcMenuLabel(item)
    if label:find("PC",1,true) or label=="LOG OFF" then hits=hits+1 end
  end
  return hits>=2 and pcMenuLabel(items[#items])=="LOG OFF"
end

local function pcMainItems(items)
  if type(items)~="table" or #items<4 then return false end
  local labels={}
  for i,item in ipairs(items) do labels[i]=pcMenuLabel(item) end
  return labels[1]:find("WITHDRAW",1,true)
      and labels[2]:find("DEPOSIT",1,true)
      and labels[3]:find("RELEASE",1,true)
      and labels[4]:find("CHANGE BOX",1,true)
end

local function pcActionItems(items)
  if type(items)~="table" or #items<3 then return false end
  local a=pcMenuLabel(items[1])
  return (a=="WITHDRAW" or a=="DEPOSIT")
      and pcMenuLabel(items[2])=="STATS"
      and pcMenuLabel(items[3])=="CANCEL"
end

-- Player item-storage PC. Gen I exposes these through generic Menu/ListMenu
-- states, while Gold has a dedicated ItemPcMenu. Keep the Gen I recognizers
-- narrow so ordinary Bag, Mart, and arbitrary mod lists are never claimed.
local function pcItemRootItems(items)
  if type(items)~="table" or #items<4 then return false end
  local labels={}
  for i,item in ipairs(items) do labels[i]=pcMenuLabel(item) end
  if labels[1]~="WITHDRAW ITEM" or labels[2]~="DEPOSIT ITEM"
      or labels[3]~="TOSS ITEM" then return false end
  local last=labels[#labels]
  return last=="LOG OFF" or last=="TURN OFF"
end

function GoldCompat.pcItemListTitle(title)
  local t=tostring(title or ""):upper()
  return t=="WITHDRAW ITEM" or t=="DEPOSIT ITEM" or t=="TOSS ITEM"
end

local function pcItemListStateInStack(game)
  if not (game and game.stack and game.stack.states) then return nil end
  for i=#game.stack.states,1,-1 do
    local state=game.stack.states[i]
    if state and state.__gen3uiPCItemList then return state end
  end
  return nil
end

function GoldCompat.pcListTitle(title)
  local t=tostring(title or ""):upper()
  if t=="PARTY (DEPOSIT)" or t=="CHANGE BOX" then return true end
  if t:match("^BOX %d+ %(WITHDRAW%)$") then return true end
  if t:match("^BOX %d+ %(RELEASE%)$") then return true end
  return false
end

local function isPCOwnedState(state)
  if not state then return false end
  -- Gen I marks its PC states with __gen3uiPC* flags. Gen II's native
  -- PcMenu/BoxMenu integration predates those flags and identifies the same
  -- replacement surfaces through __gen3uiGoldOverlayKind instead. The 2.2.12
  -- cleanup only recognized the Gen I spelling, so every Gen II PC frame
  -- released the shared Pokédex 3D actor before drawGoldBoxMenu reacquired it.
  -- The model therefore rendered correctly but its animation clock, yaw/pitch
  -- and zoom were reset to zero every frame. Treat BOTH ownership vocabularies
  -- as the same PC surface.
  local goldKind=tostring(state.__gen3uiGoldOverlayKind or "")
  return state.__gen3uiPCAccess
    or state.__gen3uiPCMain
    or state.__gen3uiPCList
    or state.__gen3uiPCAction
    or state.__gen3uiPCItemRoot
    or state.__gen3uiPCItemList
    or goldKind=="pc-root"
    or goldKind=="pc-box"
    or goldKind=="pc-item"
    or goldKind=="centerpc"
end

local function pcStateInStack(game)
  if not (game and game.stack and game.stack.states) then return nil end
  for i=#game.stack.states,1,-1 do
    local state=game.stack.states[i]
    if isPCOwnedState(state) then return state end
  end
  return nil
end


function GoldCompat.supportedOverworldMenuState(state)
  if not state then return false end

  -- These are the menu classes for which this mod has complete replacement
  -- renderers. Everything else fails safely to the native implementation.
  if state.__gen3uiStart then return true end
  if state.__gen3uiHangingOptions then return true end
  if state.__gen3uiHangingMods then return true end
  if state.__gen3uiHangingTrainer then return true end
  if getmetatable(state)==BagMenu then return true end
  if getmetatable(state)==PartyMenu then return true end
  if getmetatable(state)==MoveLearnMenu then return true end
  if state.__gen3uiPokedex then return true end
  if state.__gen3uiPokedexAction then return true end
  if state.__gen3uiDexEntry then return true end

  -- Bag item action menus are marked explicitly by our own hook.
  if state.__gen3uiBagAction or state.__gen3uiBag then return true end
  if isPCOwnedState(state) then return true end
  if state.__gen3uiShopMain or state.__gen3uiShopList
      or state.__gen3uiShopQuantity then return true end

  return false
end


local function canIntegrateMoveLearn(game, moveMenu)
  if not GoldCompat.pokemonPresentationEnabled() then return false end
  if not (State.activeTMParty and moveMenu and moveMenu.mon) then return false end
  if not stateExistsInStack(game, State.activeTMParty) then return false end

  local party = State.activeTMParty.party or (game.save and game.save.party) or {}
  local selected = math.max(1, math.min(State.activeTMParty.index or 1, #party))
  return party[selected] == moveMenu.mon
end

